import type { ThemedVariant, ThemeFile } from "./lib.js";

function v(
  grade: number,
  skill: string,
  base: string,
  prompt: string,
  promptEn: string,
  procedureNote: string,
  procedureNoteEn: string,
  emoji?: string,
): ThemedVariant {
  return { grade, skill, base, prompt, promptEn, procedureNote, procedureNoteEn, ...(emoji ? { emoji } : {}) };
}

